                    groups.setdefault(key, []).append((r, c))
        for key, pts in groups.items():
            if len(pts) < 2:
                continue
            lo = min(r for r, c in pts)
            hi = max(r for r, c in pts)
            hits = []
            for r in range(lo, hi + 1):
                c = r - key if slope == 1 else key - r
                if 0 <= c < w:
                    if grid[r][c] == 6:
                        hits.append((r, c))
                    else:
                        out[r][c] = 1
            for r, c in hits:
                for k in range(-max(h, w), max(h, w) + 1):
                    rr = r + k
                    cc = c - k if slope == 1 else c + k
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 6
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 6):
                out[r][c] = grid[r][c]
    return out
